void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    float stripe = step(0.5, fract(uv.x * 8.0));
    float wave = 0.5 + 0.5 * sin(uv.y * 18.0 + uv.x * 3.0);
    vec3 a = vec3(0.90, 0.25, 0.30);
    vec3 b = vec3(0.15, 0.55, 0.85);
    fragColor = vec4(mix(a, b, stripe) * (0.6 + 0.4 * wave), 1.0);
}
